int num(dynamic x)=>x is num?x.toInt():int.tryParse('$x')??0; double val(dynamic x)=>x is num?x.toDouble():double.tryParse('$x')??0; String rs(dynamic x)=>'₹${val(x).toStringAsFixed(0)}';
void main()=>runApp(const RentFlowApp());
class RentFlowApp extends StatelessWidget{const RentFlowApp({super.key});Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'RentFlow',theme:ThemeData(useMaterial3:true,scaffoldBackgroundColor:bg,colorScheme:ColorScheme.fromSeed(seedColor:primary)),home:const Splash());}
class Splash extends StatefulWidget{const Splash({super.key});State<Splash> createState()=>_Splash();}
class _Splash extends State<Splash>{void initState(){super.initState();Future.delayed(const Duration(milliseconds:1200),()async{final p=await SharedPreferences.getInstance();if(!mounted)return;Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>(p.getString('shop')??'').isEmpty?const ShopPage():const Shell()));});}Widget build(BuildContext c)=>Scaffold(backgroundColor:Colors.white,body:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Container(width:92,height:92,decoration:BoxDecoration(color:primary,borderRadius:BorderRadius.circular(26)),child:const Icon(Icons.swap_horiz_rounded,color:Colors.white,size:58)),const SizedBox(height:18),const Text('RentFlow',style:TextStyle(fontSize:34,fontWeight:FontWeight.w900,color:ink)),const Text('By PaliaAPK HUB',style:TextStyle(color:primary,fontWeight:FontWeight.w800)),const Text('Developer by ShanPalia',style:TextStyle(color:muted))])));}
class Store{late SharedPreferences p;List<Map<String,dynamic>> items=[],customers=[],rentals=[];String shop='',owner='',phone='';Future<void> load()async{p=await SharedPreferences.getInstance();shop=p.getString('shop')??'';owner=p.getString('owner')??'';phone=p.getString('phone')??'';items=read('items');customers=read('customers');rentals=read('rentals');}List<Map<String,dynamic>> read(String k){try{return(List<Map<String,dynamic>>).from((jsonDecode(p.getString(k)??'[]')as List).map((e)=>Map<String,dynamic>.from(e)));}catch(_){return[];}}Future<void> save()async{await p.setString('items',jsonEncode(items));await p.setString('customers',jsonEncode(customers));await p.setString('rentals',jsonEncode(rentals));}Future<void> shopSave(String n,String o,String ph)async{shop=n.trim();owner=o.trim();phone=ph.trim();await p.setString('shop',shop);await p.setString('owner',owner);await p.setString('phone',phone);}}
class ShopPage extends StatefulWidget{const ShopPage({super.key});State<ShopPage> createState()=>_Shop();}
class _Shop extends State<ShopPage>{final n=TextEditingController(),o=TextEditingController(),p=TextEditingController();Future<void> save()async{if(n.text.trim().isEmpty||o.text.trim().isEmpty)return;final s=Store();await s.load();await s.shopSave(n.text,o.text,p.text);if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Shell()));}Widget field(TextEditingController x,String t,IconData i)=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:x,decoration:InputDecoration(labelText:t,prefixIcon:Icon(i,color:primary),filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none))));Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:ListView(padding:const EdgeInsets.all(22),children:[const SizedBox(height:30),const Icon(Icons.storefront,color:primary,size:58),const SizedBox(height:10),const Text('Register Your Shop',textAlign:TextAlign.center,style:TextStyle(fontSize:29,fontWeight:FontWeight.w900)),const SizedBox(height:25),field(n,'Shop name',Icons.store),field(o,'Owner name',Icons.person),field(p,'Phone',Icons.phone),FilledButton(onPressed:save,style:FilledButton.styleFrom(backgroundColor:primary,minimumSize:const Size.fromHeight(54)),child:const Text('Continue')),const SizedBox(height:18),const Center(child:Text('RentFlow • By PaliaAPK HUB • Developer by ShanPalia',style:TextStyle(color:muted,fontSize:12)))])));}}
class Shell extends StatefulWidget{const Shell({super.key});State<Shell> createState()=>_Shell();}
class _Shell extends State<Shell>{final s=Store();int tab=0;bool ready=false;void initState(){super.initState();s.load().then((_){if(mounted)setState(()=>ready=true);});}void refresh()=>setState((){});Widget build(BuildContext c){if(!ready)return const Scaffold(body:Center(child:CircularProgressIndicator(color:primary)));final pages=[Home(s:s,r:refresh),Items(s:s,r:refresh),Customers(s:s,r:refresh),Reports(s:s),Settings(s:s,r:refresh)];return WillPopScope(onWillPop:()async{if(tab!=0){setState(()=>tab=0);return false;}return true;},child:Scaffold(body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.inventory_2_outlined),selectedIcon:Icon(Icons.inventory_2),label:'Items'),NavigationDestination(icon:Icon(Icons.people_outline),selectedIcon:Icon(Icons.people),label:'Customers'),NavigationDestination(icon:Icon(Icons.bar_chart_outlined),selectedIcon:Icon(Icons.bar_chart),label:'Reports'),NavigationDestination(icon:Icon(Icons.settings_outlined),selectedIcon:Icon(Icons.settings),label:'Settings')]));}}
Widget header(String a,String b)=>Padding(padding:const EdgeInsets.fromLTRB(18,18,18,10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(a,style:const TextStyle(fontSize:30,fontWeight:FontWeight.w900,color:ink)),Text(b,style:const TextStyle(color:muted))]));
class Home extends StatelessWidget{final Store s;final VoidCallback r;const Home({required this.s,required this.r,super.key});Widget build(BuildContext c)=>SafeArea(child:ListView(padding:const EdgeInsets.all(18),children:[Text(s.shop,style:const TextStyle(fontSize:25,fontWeight:FontWeight.w900)),const Text('Rental Management',style:TextStyle(color:muted)),const SizedBox(height:18),Row(children:[stat('Items','${s.items.length}'),stat('Customers','${s.customers.length}'),stat('Issued','${s.rentals.where((x)=>num(x['received'])<num(x['qty'])).length}')]),const SizedBox(height:15),FilledButton.icon(onPressed:()=>rental(c,s,r),icon:const Icon(Icons.add_circle),label:const Text('New Rental'),style:FilledButton.styleFrom(backgroundColor:primary,minimumSize:const Size.fromHeight(56))),const SizedBox(height:14),Row(children:[act('Item',Icons.inventory_2,()=>item(c,s,r)),act('Customer',Icons.person_add,()=>customer(c,s,r)),act('Invoice',Icons.receipt_long,()=>invoice(c,s)),act('Receive',Icons.assignment_return,()=>receive(c,s,r))]),const SizedBox(height:20),const Text('Recent Rentals',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),...s.rentals.reversed.take(8).map((x)=>Card(child:ListTile(leading:const CircleAvatar(backgroundColor:mint,child:Icon(Icons.inventory_2,color:primary)),title:Text('${x['customer']}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${x['item']} • Qty ${x['qty']}'),trailing:Text(rs(x['amount']),style:const TextStyle(fontWeight:FontWeight.w900)))))]));}
Widget stat(String a,String b)=>Expanded(child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(b,style:const TextStyle(fontSize:21,fontWeight:FontWeight.w900)),Text(a,style:const TextStyle(color:muted,fontSize:12))]))));Widget act(String t,IconData i,VoidCallback f)=>Expanded(child:InkWell(onTap:f,child:Container(margin:const EdgeInsets.only(right:5),padding:const EdgeInsets.symmetric(vertical:12),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(15)),child:Column(children:[Icon(i,color:primary),Text(t,style:const TextStyle(fontSize:11,fontWeight:FontWeight.w800))]))));}
class Items extends StatelessWidget{final Store s;final VoidCallback r;const Items({required this.s,required this.r,super.key});Widget build(BuildContext c)=>SafeArea(child:Column(children:[header('Items','Rental inventory'),Expanded(child:s.items.isEmpty?const Center(child:Text('No items yet',style:TextStyle(color:muted))):ListView.builder(itemCount:s.items.length,itemBuilder:(_,i){final x=s.items[i];return ListTile(leading:const CircleAvatar(backgroundColor:mint,child:Icon(Icons.inventory_2,color:primary)),title:Text('${x['name']}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('Qty ${num(x['qty'])} • Rent ${rs(x['rent'])}'));})),btn('Add Item',()=>item(c,s,r))]));}
class Customers extends StatelessWidget{final Store s;final VoidCallback r;const Customers({required this.s,required this.r,super.key});Widget build(BuildContext c)=>SafeArea(child:Column(children:[header('Customers','Customer records'),Expanded(child:s.customers.isEmpty?const Center(child:Text('No customers yet',style:TextStyle(color:muted))):ListView.builder(itemCount:s.customers.length,itemBuilder:(_,i){final x=s.customers[i];return ListTile(onTap:()=>customerReport(c,s,'${x['name']}'),leading:const CircleAvatar(backgroundColor:mint,child:Icon(Icons.person,color:primary)),title:Text('${x['name']}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${x['phone']??''}'),trailing:const Icon(Icons.chevron_right));})),btn('New Customer',()=>customer(c,s,r))]));}
class Reports extends StatelessWidget{final Store s;const Reports({required this.s,super.key});Widget build(BuildContext c)=>SafeArea(child:ListView(padding:const EdgeInsets.all(18),children:[header('Reports','Rental business overview'),Row(children:[metric('Issued','${s.rentals.where((x)=>num(x['received'])<num(x['qty'])).length}'),metric('Returned','${s.rentals.where((x)=>num(x['received'])>=num(x['qty'])).length}')]),const SizedBox(height:15),const Text('Rental History',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),...s.rentals.reversed.map((x)=>Card(child:ListTile(title:Text('${x['customer']} • ${x['item']}'),subtitle:Text('${x['date']} • Qty ${x['qty']}'),trailing:Text(rs(x['amount'])))))]));}}
Widget metric(String a,String b)=>Expanded(child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(a,style:const TextStyle(color:muted)),Text(b,style:const TextStyle(fontSize:24,fontWeight:FontWeight.w900))]))));
class Settings extends StatelessWidget{final Store s;final VoidCallback r;const Settings({required this.s,required this.r,super.key});Widget build(BuildContext c)=>SafeArea(child:ListView(padding:const EdgeInsets.all(18),children:[const Text('Settings',style:TextStyle(fontSize:31,fontWeight:FontWeight.w900,color:ink)),const SizedBox(height:14),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('RentFlow',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const Text('By PaliaAPK HUB',style:TextStyle(color:primary,fontWeight:FontWeight.w800)),const Text('Developer by ShanPalia',style:TextStyle(color:muted)),Text(s.shop,style:const TextStyle(fontWeight:FontWeight.w800))]))),tile('Shop Profile','${s.shop} • ${s.owner}',Icons.store,()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const ShopPage())).then((_){s.load().then((_){r();});})),tile('Check for App Update','Check latest RentFlow version',Icons.system_update_alt,()=>update(c)),tile('PaliaAPK HUB Website','Open website',Icons.language,()=>launchUrl(Uri.parse(websiteUrl),mode:LaunchMode.externalApplication)),const SizedBox(height:15),Center(child:Text('RentFlow $appVersion',style:const TextStyle(color:muted))) ]));}Widget tile(String a,String b,IconData i,VoidCallback f)=>Card(child:ListTile(onTap:f,leading:CircleAvatar(backgroundColor:mint,child:Icon(i,color:primary)),title:Text(a,style:const TextStyle(fontWeight:FontWeight.w900)),subtitle:Text(b),trailing:const Icon(Icons.chevron_right)));}
Widget tile(String a,String b,IconData i,VoidCallback f)=>Card(child:ListTile(onTap:f,leading:CircleAvatar(backgroundColor:mint,child:Icon(i,color:primary)),title:Text(a,style:const TextStyle(fontWeight:FontWeight.w900)),subtitle:Text(b),trailing:const Icon(Icons.chevron_right)));
Widget btn(String t,VoidCallback f)=>Padding(padding:const EdgeInsets.all(14),child:FilledButton.icon(onPressed:f,icon:const Icon(Icons.add),label:Text(t),style:FilledButton.styleFrom(backgroundColor:primary,minimumSize:const Size.fromHeight(52))));
Future<void> item(BuildContext c,Store s,VoidCallback r)async{final n=TextEditingController(),q=TextEditingController(text:'1'),p=TextEditingController(text:'0');final ok=await showDialog<bool>(context:c,builder:(x)=>AlertDialog(title:const Text('Add Item'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Item name')),TextField(controller:q,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantity')),TextField(controller:p,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Rent price'))]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Save'))]));if(ok==true&&n.text.trim().isNotEmpty){s.items.add({'name':n.text.trim(),'qty':num(q.text),'available':num(q.text),'rent':val(p.text)});await s.save();r();}}
Future<void> customer(BuildContext c,Store s,VoidCallback r)async{final n=TextEditingController(),p=TextEditingController();final ok=await showDialog<bool>(context:c,builder:(x)=>AlertDialog(title:const Text('New Customer'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Name')),TextField(controller:p,decoration:const InputDecoration(labelText:'Phone'))]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Save'))]));if(ok==true&&n.text.trim().isNotEmpty){s.customers.add({'name':n.text.trim(),'phone':p.text.trim()});await s.save();r();}}
Future<void> rental(BuildContext c,Store s,VoidCallback r)async{if(s.items.isEmpty||s.customers.isEmpty){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Add item and customer first.')));return;}String it='${s.items.first['name']}',cu='${s.customers.first['name']}';final q=TextEditingController(text:'1'),a=TextEditingController(text:'0');final ok=await showDialog<bool>(context:c,builder:(x)=>StatefulBuilder(builder:(x,d)=>AlertDialog(title:const Text('New Rental'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:it,items:s.items.map((e)=>DropdownMenuItem(value:'${e['name']}',child:Text('${e['name']}'))).toList(),onChanged:(v)=>d(()=>it=v??it),decoration:const InputDecoration(labelText:'Item')),DropdownButtonFormField<String>(initialValue:cu,items:s.customers.map((e)=>DropdownMenuItem(value:'${e['name']}',child:Text('${e['name']}'))).toList(),onChanged:(v)=>d(()=>cu=v??cu),decoration:const InputDecoration(labelText:'Customer')),TextField(controller:q,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantity')),TextField(controller:a,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount'))]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Create'))])));if(ok==true){final qty=num(q.text),item=s.items.firstWhere((e)=>'${e['name']}'==it);item['available']=(num(item['available'])-qty).clamp(0,999999);s.rentals.add({'item':it,'customer':cu,'qty':qty,'received':0,'amount':val(a.text),'date':DateTime.now().toString().substring(0,10)});await s.save();r();}}
Future<void> receive(BuildContext c,Store s,VoidCallback r)async{final a=s.rentals.where((x)=>num(x['received'])<num(x['qty'])).toList();if(a.isEmpty){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('No issued rental.')));return;}int i=0;final ok=await showDialog<bool>(context:c,builder:(x)=>StatefulBuilder(builder:(x,d)=>AlertDialog(title:const Text('Receive Item'),content:DropdownButtonFormField<int>(initialValue:i,items:[for(int j=0;j<a.length;j++)DropdownMenuItem(value:j,child:Text('${a[j]['customer']} • ${a[j]['item']}'))],onChanged:(v)=>d(()=>i=v??0)),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Receive'))])));if(ok==true){final z=a[i];final item=s.items.firstWhere((e)=>'${e['name']}'=='${z['item']}');item['available']=num(item['available'])+num(z['qty'])-num(z['received']);z['received']=z['qty'];await s.save();r();}}
Future<void> invoice(BuildContext c,Store s)=>showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Invoice'),content:Text('RentFlow\n${s.shop}\nBy PaliaAPK HUB\n\nUse your rental records to prepare the invoice.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));
Future<void> customerReport(BuildContext c,Store s,String name)=>showDialog(context:c,builder:(_){final a=s.rentals.where((x)=>'${x['customer']}'==name).toList();return AlertDialog(title:Text(name),content:SizedBox(width:320,child:ListView(shrinkWrap:true,children:a.map((x)=>ListTile(title:Text('${x['item']}'),subtitle:Text('${x['date']} • Qty ${x['qty']}'),trailing:Text(rs(x['amount'])))).toList())),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]);});
Future<void> update(BuildContext c)async{showDialog(context:c,barrierDismissible:false,builder:(_)=>const Center(child:CircularProgressIndicator(color:primary)));try{final q=await http.get(Uri.parse(updateUrl)).timeout(const Duration(seconds:8));if(!c.mounted)return;Navigator.pop(c);final d=jsonDecode(q.body);final latest='${d['version']??appVersion}';if(q.statusCode==200&&latest!=appVersion){showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Update available'),content:Text('RentFlow $latest is available.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Later')),FilledButton(onPressed:()=>launchUrl(Uri.parse('${d['url']??websiteUrl}'),mode:LaunchMode.externalApplication),child:const Text('Update'))]));}else{showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('You are up to date'),content:Text('RentFlow $appVersion is the latest version.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('OK'))]));}}catch(_){if(c.mounted){Navigator.pop(c);ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Could not check for updates.')));}}}
